export class DashCompleteProvider implements CompletionItemProvider {
  constructor() {}

  provideCompletionItems(document: TextDocument, position: Position): ProviderResult&lt;CompletionItem[]&gt; {
    const doc = workspace.getDocument(document.uri)
    if (!doc) return []

    const wordRange = doc.getWordRangeAtPosition(Position.create(position.line, position.character - 2))
    if (!wordRange) return []

    const preWord = document.getText(wordRange)

    return this.gatherWords()
      .filter(word =&gt;
        word.indexOf(preWord) &lt; 0 &amp;&amp;
        preWord.indexOf(word) &lt; 0)
      .map&lt;CompletionItem&gt;(word =&gt; ({
        "label": `${word}`,
        "kind": CompletionItemKind.Text,
        "insertText": `${word}`
      }))
  }
